import{_ as e,o as a,c as r,a0 as d}from"./chunks/framework.DoRPXVp_.js";const u=JSON.parse('{"title":"Agent Platform","description":"","frontmatter":{"title":"Agent Platform"},"headers":[],"relativePath":"agent/index.md","filePath":"agent/index.md"}'),o={name:"agent/index.md"};function n(i,t,s,l,c,g){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="agent-platform" tabindex="-1">Agent Platform <a class="header-anchor" href="#agent-platform" aria-label="Permalink to &quot;Agent Platform&quot;">​</a></h1><p>Lattice provides two ways for AI agents to join the WireGuard mesh:</p><table tabindex="0"><thead><tr><th>Method</th><th>Command</th><th>Isolation</th><th>Privilege</th></tr></thead><tbody><tr><td><strong>Regular node</strong></td><td><code>lattice up</code></td><td>None (host process)</td><td>root / <code>CAP_NET_ADMIN</code></td></tr><tr><td><strong>Sandbox</strong></td><td><code>lattice sandbox start</code></td><td>gVisor user-space netstack</td><td><strong>Zero-privilege</strong></td></tr></tbody></table><p>The Sandbox is the recommended approach for AI agent workloads — it runs entirely in user space, requires no kernel capabilities, and integrates with the same NATS signaling, ICE, and LRP infrastructure as regular nodes.</p><h2 id="community-vs-pro" tabindex="-1">Community vs Pro <a class="header-anchor" href="#community-vs-pro" aria-label="Permalink to &quot;Community vs Pro&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>Community</th><th>Pro</th></tr></thead><tbody><tr><td>gVisor user-space network stack</td><td>✅</td><td>✅</td></tr><tr><td>NATS registration + ICE/LRP tunneling</td><td>✅</td><td>✅</td></tr><tr><td>Credential persistence (restart-safe)</td><td>✅</td><td>✅</td></tr><tr><td>Local file audit (<code>/tmp/lattice-audit-&lt;name&gt;.jsonl</code>)</td><td>✅</td><td>✅</td></tr><tr><td>Egress policy filtering (<code>EgressFilter</code>, <code>--egress-allow</code>)</td><td>❌</td><td>✅</td></tr><tr><td>Inbound port forwarding (<code>--forward</code>)</td><td>❌</td><td>✅</td></tr><tr><td>SOCKS5 proxy (<code>--proxy-addr</code>)</td><td>❌</td><td>✅</td></tr><tr><td>NATS flow audit (server-side <code>la_flow_events</code>)</td><td>❌</td><td>✅</td></tr></tbody></table><h2 id="sub-agent-architecture" tabindex="-1">Sub-agent Architecture <a class="header-anchor" href="#sub-agent-architecture" aria-label="Permalink to &quot;Sub-agent Architecture&quot;">​</a></h2><p>Agents can delegate identity to child agents via the <strong>Delegate API</strong> — a parent agent issues a short-TTL token that a sub-agent uses to self-register with a constrained identity (<code>AgentIdentity.spec.parentRef</code>).</p><h2 id="quick-navigation" tabindex="-1">Quick Navigation <a class="header-anchor" href="#quick-navigation" aria-label="Permalink to &quot;Quick Navigation&quot;">​</a></h2><ul><li><a href="/agent/sandbox">Sandbox (Community)</a> — full guide: startup flow, CLI reference, credential persistence, AI framework integration</li><li><a href="/agent/sandbox-pro">Sandbox (Pro)</a> — EgressFilter, ForwardListener, SOCKS5 proxy, NATS audit</li><li><a href="/agent/delegate-api">Sub-agent Delegate API</a> — CRD fields, HTTP endpoint, curl and Python examples</li></ul>',10)])])}const p=e(o,[["render",n]]);export{u as __pageData,p as default};
